from pydantic import BaseModel, Field

class Paper(BaseModel):
    """One provided paper with its title and which other provided papers it references."""
    title: str | None = Field(description="This paper's title as it appears in the document")
    references: list[str] = Field(
        description="Titles of OTHER provided papers (known from document summaries) that appear in this paper's reference list"
    )

class Parse(BaseModel):
    papers: list[Paper]
